 "scratch": "设计三个游戏得分：A得325分，B得410分，C得298分。规则是每100分兑换1元，不足100分的部分按比例换算为角和分（即除以100得到元）。A=3.25元，B=4.10元，C=2.98元。比较大小：4.10 > 3.25 > 2.98。最高分是B。",
 "solver_code": "from decimal import Decimal

def solve():
    # 得分
    score_a = 325
    score_b = 410
    score_c = 298

    # 转换为元 (除以100)
    money_a = Decimal(str(score_a)) / Decimal('100')
    money_b = Decimal(str(score_b)) / Decimal('100')
    money_c = Decimal(str(score_c)) / Decimal('100')

    # 比较大小
    max_money = max(money_a, money_b, money_c)

    # 确定获胜者
    if max_money == money_a:
        winner = '小明'
    elif max_money == money_b:
        winner = '小红'
    else:
        winner = '小刚'

    return [winner]",
